"""本地审核页：3秒真连续帧、固定10时刻、来源与阻断原因。"""
import json,pathlib,argparse,html
def load(p):return json.loads(p.read_text(encoding='utf8'))
def main():
 p=argparse.ArgumentParser();p.add_argument('--output',type=pathlib.Path,required=True);a=p.parse_args();out=a.output
 reg=load(out/'registration.json');ev={s['scene']:s for s in load(out/'evidence_summary.json')['scenes']};ms={s['scene']:s for s in load(out/'mask_summary.json')};gu={s['scene']:s for s in load(out/'guard_summary.json')['scenes']};summary=load(out/'summary.json');obs=load(out/'observations.json') if (out/'observations.json').exists() else {}
 sections=[]
 names={'scene_0230':'0230 · 棕色跨界车 / actor22','scene_0255':'0255 · 围栏后的浅色SUV / actor25','official_000':'第三场景 official_000 · 右侧黑色MPV / actor12'}
 for s in reg['scenes']:
  n=s['name'];e=ev[n];m=ms[n];g=gu[n];facts=obs.get(n,{});s0=s['source_frames'][0];s1=s['source_frames'][-1]
  rows=''.join(f'<li>{html.escape(t)}</li>' for t in facts.get('observations',['结果待助手逐帧视觉检查。']))
  old=f'<p>旧矩形覆盖 {m["old_pixels"]:,} 像素·帧 → 本轮 {m["new_pixels"]:,}，减少 <b>{1-m["new_pixels"]/m["old_pixels"]:.1%}</b>。这是编辑范围变化，不是视觉成绩。</p>' if m['old_pixels'] else '<p>第三场景首次进入显式删除补景实验；已有原RGB/Ω缓存，未伪造旧DriveEditor或新GLB结果。</p>'
  counts=[len(g['arms'][arm]['blocked_frames']) for arm in ['precise','evidence_first']]
  status=facts.get('admission','待视觉检查，不准入下游Ω')
  sections.append(f'''<section id="{n}" data-scene="{n}">
 <div class="eyebrow">{n} / CAM{s['camera']} / 原始 f{s0}–{s1} / {s0/10:.1f}–{(s1+1)/10:.1f} 秒</div><h2>{names[n]}</h2>
 <p class="status">{html.escape(status)}</p><ul>{rows}</ul>{old}
 <div class="metrics"><span>可复制真实证据 <b>{e['evidence_pixels']/e['mask_pixels']:.2%}</b></span><span>检查源视图 <b>{e['source_views']}</b></span><span>检测器在原视频认出目标 <b>{g['source_target_detected_frames']}/30帧</b></span><span>A / B 车辆拦截 <b>{counts[0]} / {counts[1]} 帧</b></span></div>
 <p class="legend">A = 精确实例 mask + DriveEditor；B = 同一 mask，先复制通过检查的真实背景，DriveEditor 只补剩余洞。黄框只标目标，实际删除轮廓见下方绿色 mask。{'0230 的真实证据为零，B 与 A 逐像素相同，复用结果避免重复推理。' if e['evidence_pixels']==0 else ''}</p>
 <div class="toolbar"><button class="play">三栏同步播放 / 暂停</button><button class="reset">回到开头</button><label>速度 <select class="speed"><option value="1">1×</option><option value="0.5">0.5×</option><option value="0.25">0.25×</option></select></label><input class="seek" aria-label="同步进度" type="range" min="0" max="2.9" step="0.1" value="0"><span class="time">0.0 / 3.0 s</span></div>
 <div class="triplet">{''.join(f'<figure><figcaption>{label}</figcaption><video class="sync" controls muted playsinline preload="metadata" src="{n}/{file}.mp4"></video></figure>' for label,file in [('原视频 · 黄标目标','original'),('A · 仅精确 mask','precise'),('B · 真实证据 + 残余补景','evidence_first')])}</div>
 <h3>目标局部放大 · 同时看残车、邻车与围栏</h3><video class="wide" controls muted playsinline preload="metadata" src="{n}/zoom.mp4"></video><p class="small">固定裁剪覆盖全部30帧目标与邻近区域；放大仅供看细节，不提高原始分辨率。左右三栏仍为原视频 / A / B。</p>
 <details><summary>mask 与真实证据从哪里来</summary><div class="pair"><figure><figcaption>绿色：本轮精确删除轮廓</figcaption><video controls muted src="{n}/mask.mp4" preload="none"></video></figure><figure><figcaption>亮绿：可复制证据；紫色：还需生成</figcaption><video controls muted src="{n}/evidence_map.mp4" preload="none"></video></figure></div><img src="{n}/mask_comparison.jpg" loading="lazy"><p>静帧左：原图；中：旧扩大矩形（第三场景为原SAM）；右：本轮精确实例mask。box 只提示/约束，不作为删除区域。轮廓膨胀3px；阴影不自动包含，围栏应作为真实前景保留。证据来自原RGB，不是上轮生成图。</p><a href="{n}/evidence_stats.json">逐帧证据数量</a> · <a href="{n}/donor_index.json">Ω/原帧来源索引</a></details>
 <details><summary>车辆再生 guard 与旧版对照</summary><div class="pair"><figure><figcaption>A 检查 · 红框为被拦截车辆</figcaption><video controls muted src="{n}/guard_precise.mp4" preload="none"></video></figure><figure><figcaption>B 检查 · 红框为被拦截车辆</figcaption><video controls muted src="{n}/guard_evidence_first.mp4" preload="none"></video></figure></div>{f'<video class="wide" controls muted src="{n}/legacy.mp4" preload="none"></video><p>上轮完整工程的同相机同30帧直接DriveEditor补景；初窗条件历史不同，不能把与新版的全部差异严格归因于mask。</p>' if m['old_pixels'] else '<p>没有该目标的旧DriveEditor结果。</p>'}<p>GroundingDINO 检测车辆，SAM2 取检测实例与目标核心区交叠；与原图非目标实例匹配的邻车不当新车。命中则阻断，漏检不能当作通过。人工判定仍由你填写。</p><a href="{n}/guard_summary.json">guard 原始摘要</a></details>
 <details><summary>固定10个时刻逐帧看</summary><img src="{n}/contact.jpg" loading="lazy"></details>
 </section>''')
 css='''*{box-sizing:border-box}body{margin:0;background:#0b1017;color:#dae4ef;font:16px/1.65 "Microsoft YaHei",system-ui,sans-serif}main{max-width:1600px;margin:auto;padding:34px}h1{font-size:32px;line-height:1.3}h2{font-size:25px}h3{font-size:19px}.eyebrow{color:#7fabc7;font-size:13px;letter-spacing:.07em}a{color:#8bcdff}section{border-top:1px solid #344355;margin-top:45px;padding-top:28px}p{max-width:1250px}.status{border-left:4px solid #eeac60;background:#272218;padding:12px 18px;color:#ffd7a5}.metrics{display:flex;gap:16px;flex-wrap:wrap;margin:20px 0}.metrics span{background:#172434;border-radius:8px;padding:9px 14px}.metrics b{color:#93dcf4}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:20px 0}button,select{background:#203b50;color:#e7f5ff;border:1px solid #4b7088;border-radius:7px;padding:8px 13px;font:inherit;cursor:pointer}input[type=range]{flex:1;min-width:150px}figure{margin:0}figcaption{padding:10px;background:#1c2a3a}.triplet{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:18px}video,img{display:block;width:100%;background:#000}video.wide{max-width:1440px}.legend,.small{color:#aebdcb}.small{font-size:13px}details{border:1px solid #344355;border-radius:8px;padding:15px;margin:16px 0}summary{cursor:pointer;font-weight:600;margin-bottom:10px}.arch{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:25px 0}.arch b{padding:14px;background:#163b4c;border:1px solid #3f7280;border-radius:10px}.arch i{font-style:normal;color:#9ec3ce}nav{display:flex;gap:20px;flex-wrap:wrap}code{background:#192533;padding:3px 7px}@media(max-width:1000px){main{padding:20px}.triplet,.pair{grid-template-columns:1fr}h1{font-size:26px}}'''
 js='''document.querySelectorAll('section[data-scene]').forEach(s=>{const vs=[...s.querySelectorAll('video.sync')],seek=s.querySelector('.seek'),time=s.querySelector('.time');let moving=false;const sync=t=>{moving=true;vs.forEach(v=>{if(Number.isFinite(v.duration))v.currentTime=Math.min(t,v.duration-.001)});moving=false};s.querySelector('.play').onclick=()=>{if(vs.some(v=>!v.paused)){vs.forEach(v=>v.pause())}else{if(vs[0].currentTime>2.85)sync(0);vs.forEach(v=>v.play().catch(()=>{}))}};s.querySelector('.reset').onclick=()=>{vs.forEach(v=>v.pause());sync(0);seek.value=0};s.querySelector('.speed').onchange=e=>vs.forEach(v=>v.playbackRate=Number(e.target.value));seek.oninput=()=>sync(Number(seek.value));vs[0].ontimeupdate=()=>{if(moving)return;const t=vs[0].currentTime;seek.value=t;time.textContent=t.toFixed(1)+' / 3.0 s';vs.slice(1).forEach(v=>{if(!v.paused&&Math.abs(v.currentTime-t)>.12)v.currentTime=t})};vs[0].onended=()=>vs.forEach(v=>v.pause())});'''
 page=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>v77 · 三场景 DELETE 入口修复</title><style>{css}</style><main><div class="eyebrow">WS-V77-DELETE-REPAIR-20260927 / r1 · ZERO TRAINING</div><h1>精确实例 mask + 真实证据优先<br>三场景 DELETE 补景审核</h1><p>这轮集中检验两个入口修复，先看补景本身。三个场景各3秒连续真实帧，包含旧失败后段。旧GLB不修改；这里的 A/B 是送入后续Ω之前的背景候选，不能称为新的三场景完整世界重建。</p><div class="arch"><b>原RGB + SAM2实例mask</b><i>→</i><b>冻结Ω深度 / GT相机<br>真实观测warp与遮挡检查</b><i>→</i><b>可信RGB填洞<br>残余洞 → DriveEditor</b><i>→</i><b>车辆检测 + 实例检查<br>失败阻断 / 候选待复核</b></div><p>证据仅来自原RGB；GT相机/框、LiDAR用于米制及遮挡/支持检查。候选不足不证明背景从未被拍到，也可能受Ω深度误差及保守准入影响。未准入的生成结果不进入后续Ω。原有Ω碎裂/错误遮挡仍是独立问题，不能因mask修好就宣布全部资产链通过。</p><nav>{''.join(f'<a href="#{s["name"]}">{s["name"]}</a>' for s in reg['scenes'])}<a href="../v77-delete-full/index.html">上一轮完整工程 / 原位GLB对照</a><a href="report.md">技术报告与边界</a></nav>{''.join(sections)}<section><h2>复核记录</h2><p>{summary['total_videos']}段视频，共{summary['total_decoded_frames']}帧，已实际解码检查。零训练，未改Ω/Hunyuan权重，未执行MOVE。人工 verdict 留空。<a href="validation.json">像素与来源验证</a> · <a href="registration.json">固定登记</a> · <a href="observations.json">逐场景观察与准入决定</a></p></section></main><script>{js}</script></html>'''
 (out/'index.html').write_text(page,encoding='utf8');(out/'review.js').write_text(js,encoding='utf8')
if __name__=='__main__':main()
